9: function isBrief(value: unknown): value is Brief {
10:   if (!value || typeof value !== "object") return false;
11:   const brief = value as Partial<Brief>;
12:   const text = (v: unknown): v is string => typeof v === "string" && v.trim().length > 0 && v.length <= 2000;
13:   return INDUSTRIES.some((i) => i === brief.industry) && text(brief.description) && text(brief.targetCustomer)
14:     && brief.city === "new-york" && Array.isArray(brief.markets) && brief.markets.length > 0
15:     && brief.markets.length <= BOROUGHS.length && brief.markets.every((m) => BOROUGHS.includes(m))
16:     && typeof brief.monthlyBudget === "number" && Number.isFinite(brief.monthlyBudget) && brief.monthlyBudget > 0
17:     && !!brief.customerPays && typeof brief.customerPays.amount === "number"
18:     && Number.isFinite(brief.customerPays.amount) && brief.customerPays.amount >= 0
19:     && (brief.customerPays.per === "month" || brief.customerPays.per === "purchase");
20: }
