22: export async function POST(request: Request) {
23:   let brief: unknown;
24:   try {
25:     const body = await request.text();
26:     if (body.length > 12_000) return Response.json({ error: "Brief is too large." }, { status: 413 });
27:     brief = JSON.parse(body);
28:   } catch {
29:     return Response.json({ error: "Expected a JSON startup brief." }, { status: 400 });
30:   }
31:   if (!isBrief(brief)) return Response.json({ error: "Invalid startup brief." }, { status: 400 });
32:   const input = brief;
33:   const signal = AbortSignal.any([request.signal, AbortSignal.timeout(170_000)]);
34:   const stream = createUIMessageStream<AgentMessage>({
35:     async execute({ writer }) {
36:       writer.write({ type: "start" });
37:       const emit = (event: AgentEvent) => {
38:         if (!request.signal.aborted) writer.write({ type: "data-agent", data: event });
39:       };
40:       let complete = false;
41:       let hasFindings = false;
42:       const report = (event: AgentEvent) => {
43:         if (event.type === "competitor" || event.type === "campaign") hasFindings = true;
44:         emit(event);
45:       };
46:       try {
47:         complete = await runCompetitorResearch(input, signal, report);
48:       } catch (error) {
49:         emit({ type: "error", message: signal.aborted ? "Competitor search reached its time limit. Findings are partial; remaining coverage is unknown." : agentFailure(error) });
50:       } finally {
51:         if (!complete && !hasFindings && !request.signal.aborted) {
52:           try {
53:             await replayCompetitorResearch(input, emit);
54:           } catch {
55:             emit({ type: "error", message: "The recorded research could not be loaded. Competition coverage remains unknown." });
56:           }
57:         }
58:         emit({ type: "done" });
59:         writer.write({ type: "finish" });
60:       }
61:     },
62:     onError: agentFailure,
63:   });
64:   return createUIMessageStreamResponse({ stream, headers: {
65:     "Cache-Control": "no-cache, no-store",
66:     "X-Content-Type-Options": "nosniff",
67:     "X-Accel-Buffering": "no",
68:   } });
69: }

