3: const MIN_DISTANCE_METRES = 500;
4: const MAX_PLACEMENTS = 12;
5: 
6: function distanceMetres(a: Placement, b: Placement) {
7:   const radians = Math.PI / 180;
8:   const latitude = (b.latitude - a.latitude) * radians;
9:   const longitude = (b.longitude - a.longitude) * radians;
10:   const haversine = Math.sin(latitude / 2) ** 2 +
11:     Math.cos(a.latitude * radians) * Math.cos(b.latitude * radians) * Math.sin(longitude / 2) ** 2;
12:   return 2 * 6_371_000 * Math.asin(Math.sqrt(Math.min(1, haversine)));
13: }
