15: /** Keeps tract rank first, choosing at most one site per tract and spacing sites apart. */
16: export function selectPlacements(placements: Placement[], query: PlacementQuery): Placement[] {
17:   const rank = new Map(query.geoids.map((geoid, i) => [geoid, i]));
18:   // The stand-in minimum spend excludes bus shelters below $2,000 a month.
19:   const candidates = placements
20:     .filter((p) => rank.has(p.geoid) && p.carriesAds !== "no" &&
21:       (query.monthlyBudget >= 2000 || p.kind === "linknyc"))
22:     .sort((a, b) => rank.get(a.geoid)! - rank.get(b.geoid)! ||
23:       a.costPerAudienceMember - b.costPerAudienceMember);
24:   const selected: Placement[] = [];
25:   const tracts = new Set<string>();
26: 
27:   for (const placement of candidates) {
28:     if (tracts.has(placement.geoid)) continue;
