43: function heatRamp(id: LayerId, layers: TractLayers | null, heat: Heat, style: HeatStyle): ExpressionSpecification {
44:   if (style === "classic") {
45:     // The earlier ramp: fixed score stops, so every tract is tinted by its score.
46:     return [
47:       "interpolate", ["linear"], ["get", id],
48:       0, `rgba(${rgb(heat.mid)}, 0.1)`,
49:       0.5, `rgba(${rgb(heat.mid)}, 0.45)`,
50:       1, `rgba(${rgb(heat.hot)}, 0.75)`,
51:     ];
52:   }
53:   const values = Object.values(layers ?? {}).map((t) => t[id]);
54:   // Before any scores arrive there is nothing to rank, so the map stays faded.
55:   const sorted = (values.length ? values : [0, 1]).sort((a, b) => a - b);
56:   // Interpolation stops must strictly rise, and a bunched layer repeats values.
57:   const stops: number[] = [];
58:   for (const q of [FADE_BELOW, GLOW_AT, 1]) {
59:     const v = quantile(sorted, q === 1 ? 0.999999 : q);
60:     stops.push(stops.length && v <= stops[stops.length - 1] ? stops[stops.length - 1] + 1e-6 : v);
61:   }
62:   return [
63:     "interpolate", ["linear"], ["get", id],
64:     stops[0], `rgba(${rgb(heat.mid)}, 0.03)`,
65:     stops[1], `rgba(${rgb(heat.mid)}, 0.5)`,
66:     stops[2], `rgba(${rgb(heat.hot)}, 0.85)`,
67:   ];
68: }
