// POST one brief to the running app's competitor route and summarise the streamed events.
import { writeFile, mkdir } from "node:fs/promises";

const [, , file] = process.argv;
const { name, brief } = JSON.parse(await file_text(file));
const started = Date.now();

async function file_text(p) {
  const { readFile } = await import("node:fs/promises");
  return readFile(p, "utf8");
}

const res = await fetch("http://localhost:3000/api/competitors", {
  method: "POST",
  headers: { "Content-Type": "application/json" },
  body: JSON.stringify(brief),
  signal: AbortSignal.timeout(200_000),
});

if (!res.ok) {
  console.log(JSON.stringify({ name, status: res.status, body: await res.text(), seconds: 0 }));
  process.exit(0);
}

const decoder = new TextDecoder();
let buf = "";
const events = [];
for await (const chunk of res.body) {
  buf += decoder.decode(chunk, { stream: true });
  const lines = buf.split("\n");
  buf = lines.pop() ?? "";
  for (const line of lines) {
    if (!line.startsWith("data: ") || line.trim() === "data: [DONE]") continue;
    let parsed;
    try { parsed = JSON.parse(line.slice(6)); } catch { continue; }
    if (parsed.type === "data-agent") events.push(parsed.data);
  }
}

await mkdir("/tmp/opencode/runs", { recursive: true });
await writeFile(`/tmp/opencode/runs/${name}.json`, JSON.stringify({ brief, events }, null, 2));

const competitors = events.filter((e) => e.type === "competitor").map((e) => e.competitor);
const campaigns = events.filter((e) => e.type === "campaign").map((e) => e.campaign);
const research = events.find((e) => e.type === "research")?.summary;
const errors = events.filter((e) => e.type === "error").map((e) => e.message);
const mapped = (c) => !!(c.mapLocation || c.station);
const precise = (c) => {
  const l = c.mapLocation ?? (c.station ? { precision: "station" } : null);
  return l && l.precision !== "area";
};
console.log(JSON.stringify({
  name,
  seconds: Math.round((Date.now() - started) / 1000),
  competitors: competitors.map((c) => c.name),
  competitorCount: competitors.length,
  campaigns: campaigns.map((c) => ({
    competitor: c.competitor,
    title: c.title.slice(0, 70),
    kind: c.kind,
    coverage: c.coverage,
    dates: [c.startsOn, c.endsOn],
    mapped: mapped(c),
    precision: c.mapLocation?.precision ?? (c.station ? "station" : null),
    label: c.mapLocation?.label ?? c.station?.name ?? c.location,
    note: c.locationNote,
  })),
  counts: {
    campaigns: campaigns.length,
    mapped: campaigns.filter(mapped).length,
    current: campaigns.filter((c) => c.coverage === "current").length,
    currentPrecise: campaigns.filter((c) => c.coverage === "current" && precise(c)).length,
  },
  research,
  errors,
}, null, 2));

