const fs=require("fs");
const run=JSON.parse(fs.readFileSync("/tmp/opencode/runs/dating.json","utf8"));
if(run.events.at(-1)?.type!=="done") throw new Error("run incomplete");
if(run.events.some(e=>e.type==="error"||e.type==="recording")) throw new Error("run has error/recording");
if(!run.events.some(e=>e.type==="competitor")) throw new Error("no competitors");
const recording={recordedAt:new Date().toISOString(),brief:run.brief,events:run.events};
fs.writeFileSync("data/competitors/sample-run.json", JSON.stringify(recording,null,2)+"\n");
const camps=run.events.filter(e=>e.type==="campaign").map(e=>e.campaign);
console.log("recorded", recording.recordedAt, "events", run.events.length, "competitors", run.events.filter(e=>e.type==="competitor").length, "campaigns", camps.length);
console.log("bytes", fs.statSync("data/competitors/sample-run.json").size);
'

