23:   const steps = new Map();
24:   const model = new MockLanguageModelV4({ doStream: async (options) => {
25:     const discovery = options.tools.some((tool) => tool.name === "finishDiscovery");
26:     const prompt = options.prompt.find((message) => message.role === "user").content.map((part) => part.text ?? "").join("");
27:     const name = discovery ? "discovery" : competitors.find((candidate) => prompt.includes(`"name":"${candidate}"`));
28:     assert.ok(name, "Every campaign phase must be assigned a competitor");
29:     const step = steps.get(name) ?? 0;
30:     steps.set(name, step + 1);
31:     if (discovery) assert.match(prompt, /Do not search with the broad industry label alone/);
32:     else {
33:       assert.match(prompt, /station domination/);
34:       assert.match(prompt, /site:outfront.com/);
35:     }
36:     if (step === 0) assert.deepEqual(options.toolChoice, { type: "tool", toolName: "web_search" });
37:     if (name === fail) throw new Error("Search provider unavailable");
38:     if (name === timeout) throw new DOMException("Search deadline reached", "TimeoutError");
39:     let toolName, input, result;
40:     if (step < 2) {
41:       toolName = "web_search";
42:       input = { query: `${name} NYC campaign ${step}` };
43:       result = { sources: (discovery ? competitors : [name]).map((candidate) => ({ type: "url", url: url(candidate) })), action: { type: "search", query: input.query } };
44:     } else if (discovery && step <= 4) {
45:       toolName = "reportCompetitor";
46:       input = { name: competitors[step - 2], reason: "Same customers", sourceUrl: url(competitors[step - 2]) };
47:     } else if (discovery) {
48:       toolName = "finishDiscovery";
49:       input = {};
50:     } else if (!empty && (step === 2 || rejectSource && step === 3 || name === unfinished)) {
51:       toolName = "reportCampaign";
52:       input = finding(name);
53:       if (rejectSource && step === 2) input.sourceUrl = "https://unseen.example/campaign";
54:     } else {
55:       toolName = "finishResearch";
56:       input = {};
57:     }
58:     const toolCallId = `${name}-${step}`;
59:     const parts = [{ type: "stream-start", warnings: [] }, { type: "tool-call", toolCallId, toolName, input: JSON.stringify(input), ...(result ? { providerExecuted: true } : {}) }];
60:     if (result) parts.push({ type: "tool-result", toolCallId, toolName, result });
61:     parts.push({ type: "finish", finishReason: { unified: "tool-calls" }, usage: { inputTokens: { total: 1 }, outputTokens: { total: 1 } } });
62:     return { stream: new ReadableStream({ start(controller) { for (const part of parts) controller.enqueue(part); controller.close(); } }) };
63:   } });
64:   return { ...getCompetitorAI(), configured: true, model };
65: }
