node -e '
const fs=require("fs");
const run=JSON.parse(fs.readFileSync("/tmp/opencode/runs/dating5.json","utf8"));
const briefForm=fs.readFileSync("web/src/components/brief-form.tsx","utf8");
const b=run.brief;
if(![b.industry,b.description,b.targetCustomer].every(v=>briefForm.includes(v))) throw new Error("brief mismatch");
const camps=run.events.filter(e=>e.type==="campaign").map(e=>e.campaign);
const recentMapped=camps.filter(c=>(c.coverage==="recent"||c.coverage==="current")&&(c.mapLocation?.precision==="station"||c.mapLocation?.precision==="address"||c.station));
console.log("latestEvidenceOn present:",camps.filter(c=>c.latestEvidenceOn).length+"/"+camps.length,"recent mapped:",recentMapped.length);
for(const c of recentMapped) console.log(" gap campaign:",c.competitor,"|",c.title.slice(0,50),"|",c.coverage,"|",c.mapLocation?.precision||"station");
const recording={recordedAt:new Date().toISOString(),brief:b,events:run.events};
fs.writeFileSync("data/competitors/sample-run.json",JSON.stringify(recording,null,2)+"\n");
console.log("recorded competitors",run.events.filter(e=>e.type==="competitor").length,"campaigns",camps.length,"mapped",camps.filter(c=>c.mapLocation||c.station).length);
'

